import math
import pandas as pd
from scipy.stats import chi2


def transition_counts(hits: pd.Series) -> dict[str, int]:
    h = hits.astype(int).to_numpy()
    prev, curr = h[:-1], h[1:]
    return {
        "n00": int(((prev == 0) & (curr == 0)).sum()),
        "n01": int(((prev == 0) & (curr == 1)).sum()),
        "n10": int(((prev == 1) & (curr == 0)).sum()),
        "n11": int(((prev == 1) & (curr == 1)).sum()),
    }


def christoffersen_ind(hits: pd.Series) -> tuple[float, float]:
    c = transition_counts(hits)
    pi0 = c["n01"] / max(c["n00"] + c["n01"], 1)
    pi1 = c["n11"] / max(c["n10"] + c["n11"], 1)
    pi = (c["n01"] + c["n11"]) / sum(c.values())
    def ll(p: float, n_stay: int, n_hit: int) -> float:
        return (n_stay * math.log(1 - p) if p < 1 else 0.0) + (n_hit * math.log(p) if p > 0 else 0.0)
    lr = -2 * (ll(pi, c["n00"] + c["n10"], c["n01"] + c["n11"]) - ll(pi0, c["n00"], c["n01"]) - ll(pi1, c["n10"], c["n11"]))
    return lr, 1 - chi2.cdf(lr, df=1)


def main() -> None:
    df = pd.read_parquet("backtest_2025.parquet")
    hits = df["hypo_pnl"] < -df["var_99"]
    print(christoffersen_ind(hits))


if __name__ == "__main__":
    main()
